package com.chondrimaishrat.elearning.payment;
import com.chondrimaishrat.elearning.course.*; import com.chondrimaishrat.elearning.enrollment.*; import com.chondrimaishrat.elearning.patterns.SimulatedBkashPayment; import com.chondrimaishrat.elearning.user.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class PaymentService {private final CourseRepository courses;private final EnrollmentRepository enrollments;private final PaymentRepository payments;public PaymentService(CourseRepository c,EnrollmentRepository e,PaymentRepository p){courses=c;enrollments=e;payments=p;}@Transactional public void payAndEnroll(UserAccount s,Long id){Course c=courses.findById(id).orElseThrow(()->new IllegalArgumentException("Course not found."));if(c.getPrice().signum()==0)throw new IllegalArgumentException("This course is free.");if(enrollments.existsByStudentIdAndCourseId(s.getId(),id))throw new IllegalArgumentException("Already enrolled.");payments.save(new Payment(s,c,c.getPrice(),new SimulatedBkashPayment().pay(c.getPrice())));enrollments.save(new Enrollment(s,c));}}
